1431	    fn mul_wide(
1432	        &mut self,
1433	        context: &mut CodeGenContext<Emission>,
1434	        kind: MulWideKind,
1435	    ) -> Result<()> {
1436	        // Reserve rax/rdx since they're required by the `mul_wide` instruction
1437	        // being used here.
1438	        let rax = context.reg(regs::rax(), self)?;
1439	        let rdx = context.reg(regs::rdx(), self)?;
1440	
1441	        // The rhs of this binop can be in any register
1442	        let rhs = context.pop_to_reg(self, None)?;
1443	        // Mark rax as allocatable. and then force the lhs operand to be placed
1444	        // in `rax`.
1445	        context.free_reg(rax);
1446	        let lhs = context.pop_to_reg(self, Some(rax))?;
1447	
1448	        self.asm.mul_wide(
1449	            writable!(rax),
1450	            writable!(rdx),
